"""Freeze final protocol and identities after Gate A and pilot."""
import json,platform,subprocess,sys,hashlib,os
from pathlib import Path
from datetime import datetime,timezone
ROOT=Path(__file__).resolve().parents[3];OUT=ROOT/'phase12r';BENCH=ROOT/'benchmark-data/SpreadsheetBench-2'
