def main():
 if (OUT/'FREEZE.json').exists():raise SystemExit('Already frozen; refusing overwrite')
 m=json.loads((OUT/'POPULATION_MANIFEST.json').read_text());m['protocol']='FROZEN Phase12R';m['primary_population_rule']='P1 archived historical submissions only; P2 byte-unverified candidates explicitly normalized-only; P3 separate historical context';m['unique_tasks']={p:len({r['task'] for r in m['eligible'] if r['stratum']==p}) for p in ['P1','P2','P3']};(OUT/'POPULATION_MANIFEST.json').write_text(json.dumps(m,indent=2))
 spec=OUT/'PREREGISTERED_REPLAY_SPEC.md';(OUT/'PREREGISTERED_REPLAY_SPEC.sha256').write_text(sha(spec)+'  PREREGISTERED_REPLAY_SPEC.md\n')
