 freeze={'utc':env['frozen_utc'],'spec_hash':sha(spec),'population_hash':sha(OUT/'POPULATION_MANIFEST.json'),'replay_hash':sha(OUT/'replay.py'),'uno_helper_hash':sha(OUT/'uno_recalc.py'),'population_implementation_hash':sha(OUT/'population.py'),'tests_hash':sha(OUT/'test_replay.py'),'evaluator_hash':env['evaluator_hash'],'environment_hash':sha(OUT/'ENVIRONMENT.json'),'protected_history_manifest_hash':sha(OUT/'PROTECTED_HISTORY_HASHES.json'),'review_hash':sha(OUT/'STRONG_REVIEW_PREREG.md'),'pilot_ledger_hash':sha(OUT/'pilot/BASELINE_CORRECTION_LEDGER.jsonl')}
 (OUT/'FREEZE.json').write_text(json.dumps(freeze,indent=2));print(json.dumps(freeze,indent=2))
